<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { Plus } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import CityAnalyticsDrawer from '../components/CityAnalyticsDrawer.vue';
import CityAnalyticsRulesDrawer from '../components/CityAnalyticsRulesDrawer.vue';
import SafetyMaterials from '../components/SafetyMaterials.vue';
import { cityApi, draft, err, nf, notifyDownload, p, text, time, tone, useCityQuery } from '../city-analytics';
import '../city-analytics.css';
const session=useSessionStore(),canWrite=computed(()=>session.user?.permissions.includes('analytics:evaluation:publish')),c=useCityQuery({enterpriseId:'',grade:'',q:'',sort:'',order:''});
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),options=ref<any>({enterprises:[]}),rules=ref<any>(),optionsError=ref(''),detail=ref<any>(),detailLoading=ref(false),detailError=ref(''),tab=ref('entries'),rulesOpen=ref(false),createOpen=ref(false),createError=ref(''),saving=ref(false);
const sources=ref<any[]>([]),sourcesTotal=ref(0),sourcesPage=ref(1),sourcesQuery=ref(''),sourcesLoading=ref(false),sourcesError=ref(''),repairOpen=ref(false),repairTarget=ref<any>(),repairComment=ref(''),repairFiles=ref<any[]>([]),repairError=ref(''),uploading=ref(false),sourceOpen=ref(false),sourceDetail=ref<any>(),sourceError=ref(''),sourceLoading=ref(false);
const d=draft(`wrc-city-credit-${session.user?.id}`,{enterpriseId:'',sourceType:'VIOLATION',sourceId:'',severity:'GENERAL',reason:''}),form=d.value;
const visible=computed({get:()=>!!c.id.value,set:v=>{if(!v)void c.close();}}),entries=computed(()=>tab.value==='repairs'?(detail.value?.entries??[]).filter((e:any)=>e.status==='REPAIRED'):detail.value?.entries??[]),band=computed(()=>rules.value?.bands?.find((b:any)=>b.key===form.severity));let requestId=0,detailRequest=0,sourceRequest=0;
async function load(){const n=++requestId;loading.value=true;error.value='';try{const r=await api<any>(`${cityApi}/credit?${c.params()}`);if(n===requestId){rows.value=r.items;total.value=r.total;if(!rows.value.length&&r.total&&c.page.value>1)void c.paginate(1);}}catch(e){if(n===requestId)error.value=err(e);}finally{if(n===requestId)loading.value=false;}}
async function loadOptions(){optionsError.value='';try{const [o,r]=await Promise.all([api<any>(`${cityApi}/options`),api<any>(`${cityApi}/credit/rules`)]);options.value=o;rules.value=r;}catch(e){optionsError.value=err(e);}}
async function search(){const before=c.queryKey.value;await c.search();if(before===c.queryKey.value)await load();}
async function reset(){const before=c.queryKey.value;await c.reset();if(before===c.queryKey.value)await load();}
async function loadDetail(){const n=++detailRequest;detail.value=null;detailError.value='';if(!c.id.value)return;detailLoading.value=true;try{const r=await api(`${cityApi}/credit/${c.id.value}`);if(n===detailRequest)detail.value=r;}catch(e){if(n===detailRequest)detailError.value=err(e);}finally{if(n===detailRequest)detailLoading.value=false;}}
async function loadSources(append=false){if(!form.enterpriseId)return;const n=++sourceRequest;if(!append){sourcesPage.value=1;sources.value=[];}sourcesError.value='';sourcesLoading.value=true;try{const result=await api<any>(`${cityApi}/credit/sources?${p({enterpriseId:form.enterpriseId,sourceType:form.sourceType,q:sourcesQuery.value,page:sourcesPage.value,pageSize:20})}`);if(n===sourceRequest){sources.value=append?[...sources.value,...result.items]:result.items;sourcesTotal.value=result.total;}}catch(e){if(n===sourceRequest)sourcesError.value=err(e);}finally{if(n===sourceRequest)sourcesLoading.value=false;}}
function remoteSource(q:string){sourcesQuery.value=q;void loadSources();}
async function create(){if(!form.enterpriseId||!form.sourceId||!form.reason.trim())return ElMessage.warning('请选择企业、已确认来源并填写事实与依据');if(!rules.value?.active)return ElMessage.warning('请先核对并发布信用规则');saving.value=true;createError.value='';try{const id=form.enterpriseId;await api(`${cityApi}/credit/entries`,{method:'POST',body:JSON.stringify({...form,rulesVersion:rules.value.versionLabel})});createOpen.value=false;d.clear();await load();await c.open(id);await loadDetail();ElMessage.success('信用事项已确认并记录');}catch(e){createError.value=err(e);}finally{saving.value=false;}}
function openCreate(){createError.value='';if(!form.enterpriseId&&c.filters.enterpriseId)form.enterpriseId=c.filters.enterpriseId;createOpen.value=true;if(form.enterpriseId)void loadSources();}
function openRepair(entry:any){repairTarget.value=entry;repairError.value='';repairComment.value='';repairFiles.value=[];try{const saved=JSON.parse(localStorage.getItem(`wrc-credit-repair-${session.user?.id}-${entry.id}`)??'null');if(saved){repairComment.value=saved.comment??'';repairFiles.value=saved.files??[];}}catch{}repairOpen.value=true;}
async function repair(){if(!repairComment.value.trim()||!repairFiles.value.length)return ElMessage.warning('请填写修复核查意见并上传材料');saving.value=true;repairError.value='';try{detail.value=await api(`${cityApi}/credit/entries/${repairTarget.value.id}/repair`,{method:'POST',body:JSON.stringify({comment:repairComment.value.trim(),materialIds:repairFiles.value.map(f=>f.id)})});repairOpen.value=false;try{localStorage.removeItem(`wrc-credit-repair-${session.user?.id}-${repairTarget.value.id}`);}catch{}await load();ElMessage.success('修复已办理，原事项及材料已留存');}catch(e){repairError.value=err(e);}finally{saving.value=false;}}
async function viewSource(entry:any){const s=entry.ruleSnapshot?.source;if(s){sourceDetail.value=s;sourceOpen.value=true;sourceError.value='';return;}sourceOpen.value=true;sourceDetail.value=null;sourceError.value='';sourceLoading.value=true;try{const type=entry.sourceType;const path=type==='ACCIDENT'?`/safety/workspace/events/ACCIDENT/${entry.sourceId}`:type==='VIOLATION'?`/safety/workspace/events/VIOLATION/${entry.sourceId}`:type==='INSPECTION'?`/safety/workspace/inspections/${entry.sourceId}`:'';if(!path)throw new Error('历史记录未关联可追溯来源');sourceDetail.value=await api(path);}catch(e){sourceError.value=err(e);}finally{sourceLoading.value=false;}}
watch(()=>[form.enterpriseId,form.sourceType],()=>{form.sourceId='';sources.value=[];sourcesTotal.value=0;sourcesQuery.value='';if(createOpen.value&&form.enterpriseId)void loadSources();});
watch([repairComment,repairFiles],()=>{if(repairTarget.value)try{localStorage.setItem(`wrc-credit-repair-${session.user?.id}-${repairTarget.value.id}`,JSON.stringify({comment:repairComment.value,files:repairFiles.value}));}catch{}},{deep:true});
watch(c.queryKey,()=>void load(),{immediate:true});watch(c.id,()=>{tab.value='entries';void loadDetail();},{immediate:true});void loadOptions();
</script>
<template><section class="ca-page ca-collection" :class="{'ca-has-detail':!!c.id.value}" :style="{'--ca-detail-width':'700px'}" aria-label="信用管理">
 <QueryPanel :loading="loading" @search="search" @reset="reset"><QueryField label="企业"><el-select v-model="c.filters.enterpriseId" clearable filterable placeholder="全部企业" aria-label="企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></QueryField><QueryField label="信用等级"><el-select v-model="c.filters.grade" clearable placeholder="全部等级" aria-label="信用等级"><el-option v-for="g in ['A','B','C','D']" :key="g" :label="`${g}级`" :value="g"/></el-select></QueryField><QueryField label="关键词" keyword><el-input v-model="c.filters.q" clearable placeholder="企业名称或账户编号" aria-label="关键词"/></QueryField></QueryPanel>
 <div v-if="optionsError" class="ca-form-error" role="alert">{{optionsError}} <el-button link @click="loadOptions">重试</el-button></div>
 <article class="ca-card"><header class="ca-card-title"><h2>企业信用档案</h2><span class="ca-count">{{total}}</span><span class="ca-muted">平台信用记录</span><div class="ca-tools"><el-button @click="rulesOpen=true">信用规则</el-button><el-button v-if="canWrite" type="primary" :icon="Plus" @click="openCreate">记录信用事项</el-button></div></header>
 <div v-if="error" class="ca-error" role="alert"><strong>信用档案暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="ca-table" v-loading="loading"><el-table :data="rows" height="100%" :row-class-name="({row}:any)=>row.id===c.id.value?'ca-selected':''" empty-text="当前条件暂无企业信用档案" @sort-change="(v:any)=>{c.filters.sort=v.prop;c.filters.order=v.order==='descending'?'desc':'asc';search();}"><el-table-column label="企业" min-width="300"><template #default="{row}"><el-button link class="ca-company" @click="c.open(row.id)">{{row.name}}</el-button><span v-if="row.businessNo" class="ca-secondary">{{row.businessNo}}</span></template></el-table-column><el-table-column label="当前信用分" prop="score" width="150" align="right" sortable="custom"><template #default="{row}"><strong>{{nf(row.currentScore,0)}}</strong></template></el-table-column><el-table-column label="等级" width="120" align="center"><template #default="{row}"><el-tag v-if="row.grade" :type="row.grade==='A'?'success':row.grade==='B'?'primary':'warning'">{{row.grade}}</el-tag><span v-else>未建档</span></template></el-table-column><el-table-column label="最近信用事项" min-width="300"><template #default="{row}"><template v-if="row.latest"><span>{{row.latest.reason}}</span><span class="ca-secondary">{{nf(row.latest.scoreChange,0)}}分 · {{text(row.latest.status)}} · {{time(row.latest.confirmedAt||row.latest.createdAt)}}</span></template><span v-else class="ca-muted">暂无扣分记录</span></template></el-table-column><el-table-column label="操作" :width="c.narrow.value?110:220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="c.open(row.id)">详情</el-button></template></el-table-column></el-table></div><footer class="ca-foot"><span>车辆相关事项作为企业信用记录的依据，不单列车辆信用分。</span><el-pagination :current-page="c.page.value" :page-size="c.pageSize.value" :total="total" layout="total, sizes, prev, pager, next" :page-sizes="[10,20,50]" @current-change="c.paginate" @size-change="(v:number)=>c.paginate(1,v)"/></footer></article>
 <CityAnalyticsDrawer v-model="visible" title="信用档案" width="700px"><div v-if="detailError" class="ca-error" role="alert"><strong>信用详情暂时无法加载</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><el-skeleton v-else-if="detailLoading" :rows="10" animated/><template v-else-if="detail"><h2 class="ca-detail-title">{{detail.enterprise.name}}</h2><span class="ca-muted">企业信用账户</span><div class="ca-score"><strong>{{nf(detail.account?.currentScore,0)}}</strong>分<el-tag v-if="detail.account" :type="detail.account.grade==='A'?'success':'primary'">{{detail.account.grade}}级</el-tag><span class="ca-score-side">初始分 {{nf(detail.account?.initialScore,0)}}</span></div><el-tabs v-model="tab"><el-tab-pane label="信用记录" name="entries"/><el-tab-pane label="修复记录" name="repairs"/><el-tab-pane label="关联依据" name="sources"/></el-tabs><p class="ca-note">仅已确认事项计入信用。规则及来源以确认时留存为准。</p>
 <el-empty v-if="!entries.length" :description="tab==='repairs'?'暂无修复记录':'暂无信用事项'" :image-size="70"/>
 <template v-else-if="tab==='sources'"><article v-for="e in detail.entries" :key="e.id" class="ca-history"><header><strong>{{text(e.sourceType)}} · {{e.ruleSnapshot?.source?.businessNo||e.sourceId||'历史来源未留存'}}</strong></header><p>{{e.ruleSnapshot?.source?.title||e.reason}}</p><el-button link type="primary" @click="viewSource(e)">查看依据</el-button></article></template>
 <template v-else><article v-for="e in entries" :key="e.id" class="ca-history"><header><strong>{{e.reason}}</strong><span class="ca-amount">{{nf(e.scoreChange,0)}}分</span><el-tag :type="tone(e.status)">{{text(e.status)}}</el-tag></header><p>{{e.ruleSnapshot?.source?.title||e.businessNo}}</p><div class="ca-muted">确认人 {{e.confirmedBy||'—'}} · {{time(e.confirmedAt||e.createdAt)}}<br/>{{e.ruleSnapshot?.version?'适用规则 '+e.ruleSnapshot.version:'历史事项未留存规则版本'}} · 确认后 {{e.scoreAfter}}分<br/>可修复日期 {{time(e.repairEligibleAt)}}</div><p v-if="e.repairNote">修复意见：{{e.repairNote}}<span class="ca-secondary">{{e.repairedBy}} · {{time(e.repairedAt)}}</span></p><SafetyMaterials v-if="e.repairMaterials.length" :model-value="e.repairMaterials" :endpoint="`${cityApi}/credit/materials`"/><div style="display:flex;justify-content:space-between;margin-top:10px"><el-button link type="primary" @click="viewSource(e)">查看依据</el-button><el-button v-if="canWrite&&e.canRepair" type="primary" plain @click="openRepair(e)">办理修复</el-button><span v-else-if="e.status==='CONFIRMED'" class="ca-muted">{{e.scoreChange>=0?'无可恢复分值':!e.repairEligibleAt?'历史修复条件待核对':'尚未到修复日期'}}</span></div><el-collapse v-if="e.history.length"><el-collapse-item title="办理记录" :name="e.id"><p v-for="(h,i) in e.history" :key="i" class="ca-note">{{text(h.action)}} · {{h.actorName}} · {{time(h.at)}}<br/>{{h.comment}}<template v-if="h.scoreBefore!=null"> · {{h.scoreBefore}} → {{h.scoreAfter}}分</template></p></el-collapse-item></el-collapse></article></template>
 </template><template #footer><el-button @click="visible=false">关闭</el-button><el-button v-if="detail" @click="notifyDownload(`${cityApi}/credit/${detail.enterprise.id}/export`)">导出信用记录</el-button><el-button @click="rulesOpen=true">信用规则</el-button></template></CityAnalyticsDrawer>
 <CityAnalyticsRulesDrawer v-model="rulesOpen" kind="credit" @changed="loadOptions"/>
 <el-dialog v-model="createOpen" title="记录信用事项" width="660px" class="ca-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><el-alert v-if="!rules?.active" type="info" :closable="false" title="请先核对并发布信用规则。"/><el-form label-position="top"><el-form-item label="企业" required><el-select v-model="form.enterpriseId" filterable placeholder="请选择企业" aria-label="信用事项企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item label="来源类型" required><el-select v-model="form.sourceType" aria-label="来源类型"><el-option label="已确认违规" value="VIOLATION"/><el-option label="已登记认定的事故" value="ACCIDENT"/><el-option label="已完成复核的检查" value="INSPECTION"/></el-select></el-form-item><el-form-item label="关联来源" required><el-select v-model="form.sourceId" filterable remote :remote-method="remoteSource" :loading="sourcesLoading" :disabled="!form.enterpriseId" placeholder="搜索已确认记录的名称或编号" aria-label="关联来源"><el-option v-for="s in sources" :key="s.id" :label="`${s.businessNo} · ${s.title}`" :value="s.id"/><template #footer><el-button v-if="sources.length<sourcesTotal" text :loading="sourcesLoading" @click="sourcesPage++;loadSources(true)">加载更多（已显示{{sources.length}} / {{sourcesTotal}}）</el-button><span v-else class="ca-muted">共{{sourcesTotal}}条已确认来源</span></template></el-select></el-form-item><p v-if="sourcesError" class="ca-form-error">{{sourcesError}} <el-button link @click="loadSources()">重试</el-button></p><el-form-item label="事项程度" required><el-select v-model="form.severity" aria-label="事项程度"><el-option v-for="b in rules?.bands??[]" :key="b.key" :label="`${text(b.key)}（扣${b.points}分，${b.repairDays}天后可核查修复）`" :value="b.key"/></el-select></el-form-item><el-form-item label="事实与依据" required><el-input v-model="form.reason" type="textarea" :rows="4" maxlength="2000" aria-label="事实与依据"/></el-form-item></el-form><p class="ca-note">确认后按{{rules?.versionLabel}}记入企业信用；本事项拟扣{{band?.points??'—'}}分，实际变动不超过当前剩余分值。关联来源不可重复扣分，未提交内容自动保留。</p><div v-if="createError" class="ca-form-error" role="alert">{{createError}}</div><template #footer><el-button :disabled="saving" @click="createOpen=false">取消</el-button><el-button v-if="!rules?.active" @click="createOpen=false;rulesOpen=true">配置信用规则</el-button><el-button v-else type="primary" :loading="saving" @click="create">确认记入信用</el-button></template></el-dialog>
 <el-dialog v-model="repairOpen" title="办理信用修复" width="640px" class="ca-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><p>{{detail?.enterprise.name}}</p><p class="ca-note">原事项：{{repairTarget?.reason}} · {{nf(repairTarget?.scoreChange,0)}}分</p><el-form label-position="top"><el-form-item label="修复核查意见" required><el-input v-model="repairComment" type="textarea" :rows="4" maxlength="2000" aria-label="修复核查意见"/></el-form-item><el-form-item label="修复材料" required><SafetyMaterials v-model="repairFiles" :enterprise-id="detail?.enterprise.id" :editable="true" :endpoint="`${cityApi}/credit/materials`" @busy="uploading=$event"/></el-form-item></el-form><p class="ca-note">核查通过后恢复原事项实际扣分值，最高恢复至初始分。原扣分、修复意见和材料均留存。</p><div v-if="repairError" class="ca-form-error" role="alert">{{repairError}}</div><template #footer><el-button :disabled="saving||uploading" @click="repairOpen=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="uploading" @click="repair">核查通过并修复</el-button></template></el-dialog>
 <el-dialog v-model="sourceOpen" title="信用事项依据" width="620px" class="ca-dialog"><el-skeleton v-if="sourceLoading" :rows="5" animated/><p v-else-if="sourceError" class="ca-form-error">{{sourceError}}</p><template v-else-if="sourceDetail"><h3>{{sourceDetail.title}}</h3><dl class="ca-detail-meta"><dt>来源编号</dt><dd>{{sourceDetail.businessNo}}</dd><dt>来源状态</dt><dd>{{text(sourceDetail.status)}}</dd><dt>确认事实</dt><dd>{{sourceDetail.confirmedFact||sourceDetail.responsibility||sourceDetail.result||sourceDetail.description||'详见来源记录'}}</dd></dl><p class="ca-note">显示确认时留存的来源摘要；具体证据可在安全监管的对应事项中按编号查询。</p></template><template #footer><el-button @click="sourceOpen=false">关闭</el-button></template></el-dialog>
</section></template>
